/*
 * BL616 MOD->PCM->HDMI. The Apple IIgs DOC and its sound RAM are uninvolved.
 * Audio is generated by public-domain HxCMOD at exactly HDMI's 44,100 Hz.
 * SPI XFER SPACE 6 writes one 16-bit LE left/right pair per 4 bytes.
 *
 * IMPORTANT: the original NTP player is intentionally NOT included.
 * No 6502 mailbox, native DOC register writes, DOC oscillator patches,
 * sound sample-bank generation, or NTP instrument translation.
 */
#include "mcu_mod_audio.h"
#include "mcu_mod_jukebox.h"
#include "mcu_mod_format.h"
#include "mcu_mod_sample_store.h"
#include "third_party/hxcmod/hxcmod.h"
#include "fpga_spi.h"
#include "disk.h"
#include "osd_console.h"
#include "FreeRTOS.h"
#include "task.h"
#include "usb_osal.h"
#include <ctype.h>
#include <string.h>

#define PCM_SPACE 6u
#define PCM_CTRL_RESET 0x800000u
#define PCM_CTRL_ENABLE 0x800001u
#define PCM_STATUS 0x800000u
#define PCM_BLOCK_FRAMES 256u
#define PCM_BLOCK_BYTES (PCM_BLOCK_FRAMES*4u)
#define MOD_FILE_LIMIT MOD_TOTAL_FILE_MAX
#define PCM_HZ 44100u
#define MOD_PATH_CAP 128u

static modcontext s_ctx;
static msample s_pcm[PCM_BLOCK_FRAMES*2u];
static uint8_t s_status[16];
static uint8_t *s_file;  /* header+patterns only, never PCM samples */
static uint8_t s_mod_header[MOD_HEADER_PROBE];
static uint8_t s_mod_transfer[MOD_STORE_PAGE];
static uint8_t s_mod_stage_head[32],s_mod_stage_tail[32];
static volatile uint32_t s_path_seq;
static uint32_t s_seen_seq;
static char s_path[MOD_PATH_CAP];
static volatile uint32_t s_stop;
static volatile uint32_t s_replay;
static char s_last_request[MOD_PATH_CAP]; // written by modpcm task alone
static volatile uint32_t s_has_last;      // published after full path copy
static volatile mod_pcm_status_t s_state=MOD_PCM_IDLE;
/* J1 control mailbox: producer(s) publish directory and mode as a seqlock;
 * only the MOD task performs scanning, allocation and all HxCMOD calls. */
static char s_juke_path[MOD_PATH_CAP];
static volatile uint32_t s_juke_seq, s_juke_seen, s_juke_recursive;
static volatile uint32_t s_juke_count_pub, s_nav, s_once;
static void juke_publish(const char *dir,bool recursive)
{
    /* Avoid two producers corrupting the request buffer. */
    uint32_t old;
    for(;;) {
        old=__atomic_load_n(&s_juke_seq,__ATOMIC_ACQUIRE);
        if(old&1u) {
            vTaskDelay(pdMS_TO_TICKS(1));
            continue;
        }
        if(__atomic_compare_exchange_n(&s_juke_seq,&old,old+1u,
                 false,__ATOMIC_ACQ_REL,__ATOMIC_ACQUIRE))
            break;
    }
    memset(s_juke_path,0,sizeof(s_juke_path));
    memcpy(s_juke_path,dir,strlen(dir)+1u);
    s_juke_recursive=recursive?1u:0u;
    __atomic_store_n(&s_juke_seq,old+2u,__ATOMIC_RELEASE);
}
static bool take_juke(char out[MOD_PATH_CAP],bool *recursive)
{
    uint32_t a=__atomic_load_n(&s_juke_seq,__ATOMIC_ACQUIRE);
    if(!a || (a&1u) || a==s_juke_seen)return false;
    memcpy(out,s_juke_path,MOD_PATH_CAP);
    const bool r=s_juke_recursive!=0;
    uint32_t end=__atomic_load_n(&s_juke_seq,__ATOMIC_ACQUIRE);
    if(a!=end || (end&1u))return false;
    s_juke_seen=end;
    *recursive=r;
    return true;
}
bool mod_audio_jukebox_start(const char *dir,bool recursive)
{
    if(!dir || strlen(dir)>=MOD_PATH_CAP || strstr(dir,"..") ||
       dir[0]=='/' || strchr(dir,':') || strchr(dir,'\\'))return false;
    juke_publish(dir,recursive);
    return true;
}
void mod_audio_jukebox_from_last(bool recursive)
{
    /* Sentinel 0x01 is not a valid user directory name. */
    juke_publish("\001",recursive);
}
bool mod_audio_next(void)
{
    if(!__atomic_load_n(&s_juke_count_pub,__ATOMIC_ACQUIRE))return false;
    __atomic_store_n(&s_nav,1u,__ATOMIC_RELEASE);
    return true;
}
bool mod_audio_previous(void)
{
    if(!__atomic_load_n(&s_juke_count_pub,__ATOMIC_ACQUIRE))return false;
    __atomic_store_n(&s_nav,2u,__ATOMIC_RELEASE);
    return true;
}
void mod_audio_set_play_once(bool once)
{
    __atomic_store_n(&s_once,once?1u:0u,__ATOMIC_RELEASE);
}
bool mod_audio_play_once(void)
{
    return __atomic_load_n(&s_once,__ATOMIC_ACQUIRE)!=0u;
}
unsigned mod_audio_jukebox_count(void)
{
    return __atomic_load_n(&s_juke_count_pub,__ATOMIC_ACQUIRE);
}


static bool valid_path(const char *path)
{
    if(!path)return false;
    size_t n=strlen(path);
    if(n<5u || n>=MOD_PATH_CAP || strstr(path,"..") ||
       path[0]=='/' || strchr(path,':') || strchr(path,'\\'))return false;
    return path[n-4]=='.' &&
           tolower((unsigned char)path[n-3])=='m' &&
           tolower((unsigned char)path[n-2])=='o' &&
           tolower((unsigned char)path[n-1])=='d';
}
bool mod_audio_choose(const char *path)
{
    if(!valid_path(path))return false;
    __atomic_add_fetch(&s_path_seq,1u,__ATOMIC_RELEASE);
    memset(s_path,0,sizeof s_path);
    memcpy(s_path,path,strlen(path)+1u);
    __atomic_add_fetch(&s_path_seq,1u,__ATOMIC_RELEASE);
    s_state=MOD_PCM_SELECTED;
    return true;
}
static bool take_pending(char out[MOD_PATH_CAP])
{
    uint32_t a=__atomic_load_n(&s_path_seq,__ATOMIC_ACQUIRE);
    if(!a || (a&1u) || a==s_seen_seq)return false;
    memcpy(out,s_path,MOD_PATH_CAP);
    uint32_t b=__atomic_load_n(&s_path_seq,__ATOMIC_ACQUIRE);
    if(a!=b || (b&1u))return false;
    s_seen_seq=b;
    return true;
}
mod_pcm_status_t mod_audio_status(void){return s_state;}
void mod_audio_request_stop(void)
{
    __atomic_store_n(&s_stop,1u,__ATOMIC_RELEASE);
}
bool mod_audio_replay_last(void)
{
    if(!__atomic_load_n(&s_has_last,__ATOMIC_ACQUIRE))
        return false;
    __atomic_store_n(&s_replay,1u,__ATOMIC_RELEASE);
    return true;
}
static bool pcm_read_status(void)
{
    fpga_spi_xfer_read(PCM_SPACE,PCM_STATUS,s_status,sizeof s_status);
    return s_status[0]==0x50 && s_status[1]==0x43 &&
           s_status[2]==1u;
}
static uint16_t pcm_free(void)
{
    return (uint16_t)s_status[6] | (uint16_t)((uint16_t)s_status[7]<<8);
}
static uint16_t pcm_underruns(void)
{
    return (uint16_t)s_status[8] | (uint16_t)((uint16_t)s_status[9]<<8);
}
static void pcm_control(uint32_t address,uint8_t value)
{
    fpga_spi_xfer_write(PCM_SPACE,address,&value,1u);
}
static void player_release(void)
{
    pcm_control(PCM_CTRL_ENABLE,0);
    pcm_control(PCM_CTRL_RESET,0xA5u);
    hxcmod_unload(&s_ctx);
    if(s_file)vPortFree(s_file);
    s_file=NULL;
}
/* J2: bounded file parser and single-copy external sample staging. The MCU
 * only allocates the pattern table (<=132 KiB). Up to 2 MiB of PCM instrument
 * bytes are written into an exclusive high-SDRAM region via XFER SPACE1. */
static bool player_load(const char *path)
{
    fs_req_t fs;
    mod_format_t fmt;
    uint32_t off;
    bool ok=false,opened=false;
    memset(&fs,0,sizeof fs);
    fs.op=FSOP_MOD_OPEN;fs.path=path;
    if(disk_fs_request(&fs)!=0) {
        osd_log("MCU MOD: FILE OPEN FAILED");
        goto finish;
    }
    opened=true;
    const uint32_t file_size=fs.size;
    if(file_size<MOD_HEADER_PROBE || file_size>MOD_FILE_LIMIT) {
        osd_log("MCU MOD: FILE SIZE %lu UNSUPPORTED",
                (unsigned long)file_size);
        goto finish;
    }
    memset(&fs,0,sizeof fs);
    fs.op=FSOP_MOD_READ;
    fs.buf=s_mod_header;
    fs.len=MOD_HEADER_PROBE;
    if(disk_fs_request(&fs)!=0 || fs.out!=MOD_HEADER_PROBE) {
        osd_log("MCU MOD: HEADER READ FAILED");
        goto finish;
    }
    if(!mod_format_probe(s_mod_header,file_size,&fmt)) {
        osd_log("MCU MOD: BAD/UNSUPPORTED 4CH FORMAT %s",path);
        goto finish;
    }
    if(!mod_store_begin(fmt.lengths)) {
        osd_log("MCU MOD: TOO MANY SAMPLE BYTES");
        goto finish;
    }
    s_file=(uint8_t*)pvPortMalloc(fmt.prefix_bytes);
    if(!s_file) {
        osd_log("MCU MOD: NO RAM FOR %luB PATTERNS",
                (unsigned long)fmt.prefix_bytes);
        goto finish;
    }
    memcpy(s_file,s_mod_header,fmt.header_bytes);
    /* For 15-instrument MODs the initial 1084-byte probe already contains
     * part of the first pattern. Preserve those bytes, don't read past them. */
    if(fmt.header_bytes<MOD_HEADER_PROBE) {
        const uint32_t preloaded=MOD_HEADER_PROBE-fmt.header_bytes;
        memcpy(s_file+fmt.header_bytes,s_mod_header+fmt.header_bytes,
               preloaded<fmt.pattern_bytes?preloaded:fmt.pattern_bytes);
        off=MOD_HEADER_PROBE;
    }else off=MOD_HEADER_PROBE;
    while(off<fmt.prefix_bytes) {
        memset(&fs,0,sizeof fs);
        fs.op=FSOP_MOD_READ;
        fs.buf=s_file+off;
        fs.len=(fmt.prefix_bytes-off)>MOD_STORE_PAGE ?
               MOD_STORE_PAGE : fmt.prefix_bytes-off;
        if(disk_fs_request(&fs)!=0 || fs.out!=fs.len) {
            osd_log("MCU MOD: PATTERN READ FAILED");
            goto finish;
        }
        off+=fs.out;
    }
    /* Exactly the declared sample body is copied to FPGA SDRAM. An optional
     * trailing MOD tag/padding is deliberately ignored. */
    const uint16_t verify_len=(uint16_t)(fmt.sample_bytes<32u ?
                                           fmt.sample_bytes : 32u);
    for(off=0;off<fmt.sample_bytes;) {
        uint32_t len=fmt.sample_bytes-off;
        if(len>MOD_STORE_PAGE)len=MOD_STORE_PAGE;
        memset(&fs,0,sizeof fs);
        fs.op=FSOP_MOD_READ;
        fs.buf=s_mod_transfer;
        fs.len=len;
        if(disk_fs_request(&fs)!=0 || fs.out!=len ||
           !mod_store_stage(off,s_mod_transfer,(uint16_t)len)) {
            osd_log("MCU MOD: SAMPLE STAGE FAILED +%lu",
                    (unsigned long)off);
            goto finish;
        }
        if(off==0u)memcpy(s_mod_stage_head,s_mod_transfer,verify_len);
        if(off+len==fmt.sample_bytes)
            memcpy(s_mod_stage_tail,s_mod_transfer+len-verify_len,verify_len);
        off+=len;
    }
    if(verify_len &&
       (!mod_store_verify(0u,s_mod_stage_head,verify_len) ||
        !mod_store_verify(fmt.sample_bytes-verify_len,
                          s_mod_stage_tail,verify_len))) {
        osd_log("MCU MOD: FPGA SDRAM READBACK FAILED");
        goto finish;
    }
    if(!hxcmod_init(&s_ctx) ||
       !hxcmod_setcfg(&s_ctx,PCM_HZ,100,1))goto finish;
    hxcmod_external_samples(&s_ctx,MOD_SDRAM_BASE,MOD_SDRAM_CAPACITY,
                            NULL,mod_store_read,mod_store_write);
    if(!hxcmod_load(&s_ctx,s_file,(int)fmt.prefix_bytes)) {
        osd_log("MCU MOD: HxCMOD REJECTED FILE");
        goto finish;
    }
    osd_log("MCU MOD: %luB FILE, %luB PATTERNS, %luB FPGA PCM",
            (unsigned long)file_size,(unsigned long)fmt.prefix_bytes,
            (unsigned long)fmt.sample_bytes);
    ok=true;
finish:
    if(opened) {
        memset(&fs,0,sizeof fs);
        fs.op=FSOP_MOD_CLOSE;
        (void)disk_fs_request(&fs);
    }
    if(!ok) {
        hxcmod_unload(&s_ctx);
        if(s_file)vPortFree(s_file);
        s_file=NULL;
        mod_store_invalidate();
    }
    return ok;
}
/* J1: a complete MOD order-list pass ends on the HxCMOD song_wraps
 * event. HxCMOD still renders classic effect loops faithfully; the
 * wrap marker lets the host decide when to advance or stop. */
static bool pcm_send_block(bool one_pass)
{
    const uint32_t wraps=s_ctx.song_wraps;
    hxcmod_fillbuffer(&s_ctx,s_pcm,PCM_BLOCK_FRAMES,NULL);
    fpga_spi_xfer_write(PCM_SPACE,0,(const uint8_t*)s_pcm,PCM_BLOCK_BYTES);
    return one_pass && s_ctx.song_wraps!=wraps;
}
static bool start_song(const char *path)
{
    s_state=MOD_PCM_LOADING;
    if(!pcm_read_status()) {
        osd_log("MCU MOD: NEED DIRECT PCM FPGA (SPACE6 PC V1)");
        s_state=MOD_PCM_ERROR;
        return false;
    }
    if(!player_load(path)) {
        s_state=MOD_PCM_ERROR;
        return false;
    }
    memcpy(s_last_request,path,strlen(path)+1u);
    __atomic_store_n(&s_has_last,1u,__ATOMIC_RELEASE);
    pcm_control(PCM_CTRL_RESET,0xA5u);
    pcm_control(PCM_CTRL_ENABLE,1u);
    s_state=MOD_PCM_PLAYING;
    osd_log("MCU MOD: PLAY %s",path);
    return true;
}
static bool playlist_play(unsigned *idx,unsigned start)
{
    const unsigned count=mod_jukebox_count();
    for(unsigned i=start;i<count;i++) {
        const char *path=mod_jukebox_track(i);
        if(path && start_song(path)) {
            *idx=i;
            osd_log("MCU JUKE: TRACK %u/%u",i+1u,count);
            return true;
        }
        osd_log("MCU JUKE: SKIP TRACK %u",i+1u);
    }
    return false;
}
void mod_audio_task(void *arg)
{
    char requested[MOD_PATH_CAP],jukedir[MOD_PATH_CAP];
    bool playing=false,draining=false,juke_active=false,recursive=false;
    unsigned juke_index=0;
    uint32_t blocks=0,window=0;
    (void)arg;
    s_file=NULL;
    s_state=MOD_PCM_IDLE;
    osd_log("MCU MOD: DIRECT HxCMOD->HDMI READY");
    for(;;) {
        const bool selected=take_pending(requested);
        const bool jukebox=take_juke(jukedir,&recursive);
        const bool replay=__atomic_exchange_n(&s_replay,0u,__ATOMIC_ACQ_REL)!=0u;
        const uint32_t nav=__atomic_exchange_n(&s_nav,0u,__ATOMIC_ACQ_REL);
        const bool stop=__atomic_exchange_n(&s_stop,0u,__ATOMIC_ACQ_REL)!=0u;
        if(stop) {
            if(playing){player_release();playing=false;}
            draining=false;
            juke_active=false;  /* list is retained for NEXT/PREV */
            s_state=MOD_PCM_STOPPED;
            osd_log("MCU MOD: PCM STOPPED");
        }else if(jukebox) {
            if(playing){player_release();playing=false;}
            draining=false;
            juke_active=false;
            if(jukedir[0]=='\001' && jukedir[1]==0) {
                /* Work from the last successfully loaded MOD's folder. */
                const char *slash=strrchr(s_last_request,'/');
                if(s_has_last && slash) {
                    size_t n=(size_t)(slash-s_last_request);
                    memcpy(jukedir,s_last_request,n);
                    jukedir[n]=0;
                }else jukedir[0]=0; /* FAT root */
            }
            __atomic_store_n(&s_juke_count_pub,0u,__ATOMIC_RELEASE);
            if(mod_jukebox_scan(jukedir,recursive)) {
                __atomic_store_n(&s_juke_count_pub,mod_jukebox_count(),__ATOMIC_RELEASE);
                juke_index=0;
                juke_active=playlist_play(&juke_index,0);
                playing=juke_active;
            }else {
                s_state=MOD_PCM_STOPPED;
                osd_log("MCU JUKE: NO .MOD FILES FOUND");
            }
            blocks=window=0;
        }else if(selected) {
            if(playing){player_release();playing=false;}
            draining=false;
            juke_active=false;
            mod_jukebox_clear();
            __atomic_store_n(&s_juke_count_pub,0u,__ATOMIC_RELEASE);
            playing=start_song(requested);
            blocks=window=0;
        }else if(nav && mod_jukebox_count()) {
            unsigned target;
            const unsigned count=mod_jukebox_count();
            if(playing){player_release();playing=false;}
            draining=false;
            target=(nav==1u)?(juke_index+1u)%count:
                              (juke_index?juke_index-1u:count-1u);
            juke_active=playlist_play(&juke_index,target);
            /* NEXT wraps around if last items are unloadable. */
            if(!juke_active && target!=0)
                juke_active=playlist_play(&juke_index,0);
            playing=juke_active;
            blocks=window=0;
        }else if(replay && __atomic_load_n(&s_has_last,__ATOMIC_ACQUIRE)) {
            if(playing){player_release();playing=false;}
            draining=false;
            playing=start_song(s_last_request);
            blocks=window=0;
        }
        if(playing) {
            if(!pcm_read_status()) {
                osd_log("MCU MOD: FPGA PCM LINK LOST");
                player_release();playing=false;
                draining=false;juke_active=false;
                s_state=MOD_PCM_ERROR;
            }else if(draining) {
                /* Let existing FPGA PCM frames finish before clearing FIFO.
                 * Hardware may count one intentional underrun at song end. */
                if(pcm_free()>=2048u) {
                    player_release();
                    playing=false;
                    draining=false;
                    if(juke_active && juke_index+1u<mod_jukebox_count()) {
                        juke_active=playlist_play(&juke_index,juke_index+1u);
                        playing=juke_active;
                        blocks=window=0;
                    }else {
                        juke_active=false; /* reached last track, do not loop */
                        s_state=MOD_PCM_STOPPED;
                        osd_log("MCU JUKE: FINISHED / PLAY ONCE DONE");
                    }
                }
            }else if(pcm_free()>=PCM_BLOCK_FRAMES) {
                const bool done=pcm_send_block(juke_active || mod_audio_play_once());
                ++blocks;
                if(done) {
                    draining=true;
                    osd_log("MCU MOD: SONG COMPLETE (ORDER WRAP)");
                }
                // All counters come from FPGA's actual HDMI-clocked FIFO.
                if(++window>=384u) {
                    osd_log("MCU MOD: FRAMES=%lu FREE=%u UDR=%u",
                            (unsigned long)(blocks*PCM_BLOCK_FRAMES),
                            (unsigned)pcm_free(),
                            (unsigned)pcm_underruns());
                    window=0;
                }
            }
        }
        vTaskDelay(pdMS_TO_TICKS(2));
    }
}
